import { displayMatrixProduct, displayMatrixRectangle } from '../core/display-transform';
import type { SwfClip } from './swf-clip';
import type { Projectile, Vec } from '../core/types';
import type { Bounds, DisplayPlacement, SwfMatrix } from './asset-pack';

export interface ScriptBoundsSource {
  /** Declared shape bounds, including strokes; morphs return their start bounds. */
  leafBounds(id: number): Bounds | undefined;
  displayList(id: number, age: number): readonly DisplayPlacement[];
  childAge(parentId: number, age: number, placement: DisplayPlacement): number;
}

interface ChildOverride {
  age?: number;
  matrix?: SwfMatrix;
}
type Override = (
  placement: DisplayPlacement,
  age: number,
  path: readonly string[],
) => ChildOverride | undefined;

const identity: SwfMatrix = { a: 1, b: 0, c: 0, d: 1, tx: 0, ty: 0 };

/** SWF translations remain in twips throughout composition. */
function multiply(a: SwfMatrix, b: SwfMatrix): SwfMatrix {
  return {
    a: a.a * b.a + a.c * b.b,
    b: a.b * b.a + a.d * b.b,
    c: a.a * b.c + a.c * b.d,
    d: a.b * b.c + a.d * b.d,
    tx: a.a * b.tx + a.c * b.ty + a.tx,
    ty: a.b * b.tx + a.d * b.ty + a.ty,
  };
}
function transformed(bounds: Bounds, m: SwfMatrix): Bounds {
  const corners = [
    [bounds.x, bounds.y],
    [bounds.x + bounds.width, bounds.y],
    [bounds.x, bounds.y + bounds.height],
    [bounds.x + bounds.width, bounds.y + bounds.height],
  ].map(([x, y]) => ({ x: m.a * x + m.c * y + m.tx / 20, y: m.b * x + m.d * y + m.ty / 20 }));
  const x = Math.min(...corners.map((p) => p.x)),
    y = Math.min(...corners.map((p) => p.y));
  return {
    x,
    y,
    width: Math.max(...corners.map((p) => p.x)) - x,
    height: Math.max(...corners.map((p) => p.y)) - y,
  };
}
function union(a: Bounds | undefined, b: Bounds | undefined): Bounds | undefined {
  if (!a) return b;
  if (!b) return a;
  const x = Math.min(a.x, b.x),
    y = Math.min(a.y, b.y);
  return {
    x,
    y,
    width: Math.max(a.x + a.width, b.x + b.width) - x,
    height: Math.max(a.y + a.height, b.y + b.height) - y,
  };
}

interface BoundsArithmetic {
  multiply(left: SwfMatrix, right: SwfMatrix): SwfMatrix;
  transform(bounds: Bounds, matrix: SwfMatrix): Bounds;
}
const continuousBounds: BoundsArithmetic = { multiply, transform: transformed };
const twipBounds: BoundsArithmetic = {
  multiply: displayMatrixProduct,
  transform: (bounds, matrix) => {
    const rectangle = displayMatrixRectangle(matrix, {
      // Recover the declared integer twips from the legacy pixel-source API.
      // This is metadata decoding, not a truncating DisplayObject setter.
      xMin: Math.round(bounds.x * 20),
      yMin: Math.round(bounds.y * 20),
      xMax: Math.round((bounds.x + bounds.width) * 20),
      yMax: Math.round((bounds.y + bounds.height) * 20),
    });
    return {
      x: rectangle.xMin,
      y: rectangle.yMin,
      width: rectangle.xMax - rectangle.xMin,
      height: rectangle.yMax - rectangle.yMin,
    };
  },
};

/** Existing continuous approximation; retained callers need individual source qualification. */
export function scriptBounds(
  source: ScriptBoundsSource,
  id: number,
  age: number,
  matrix: SwfMatrix = identity,
  override?: Override,
  path: readonly string[] = [],
  depth = 0,
  pose?: SwfClip,
): Bounds | undefined {
  return visitBounds(continuousBounds, source, id, age, matrix, override, path, depth, pose);
}

/**
 * DisplayObject width/height arithmetic: compose float32 matrices, transform
 * declared leaf twips with ties-even BEFORE integer translation, then union.
 * Mask/alpha children participate; this is neither paint nor getBounds(target).
 * Keep integer extents until the final pixel conversion. See docs/script-bounds-arithmetic.md.
 */
export function scriptTwipBounds(
  source: ScriptBoundsSource,
  id: number,
  age: number,
  matrix: SwfMatrix = identity,
  override?: Override,
  path: readonly string[] = [],
  depth = 0,
  pose?: SwfClip,
): Bounds | undefined {
  const bounds = visitBounds(twipBounds, source, id, age, matrix, override, path, depth, pose);
  return (
    bounds && {
      x: bounds.x / 20,
      y: bounds.y / 20,
      width: bounds.width / 20,
      height: bounds.height / 20,
    }
  );
}

function visitBounds(
  arithmetic: BoundsArithmetic,
  source: ScriptBoundsSource,
  id: number,
  age: number,
  matrix: SwfMatrix = identity,
  override?: Override,
  path: readonly string[] = [],
  depth = 0,
  pose?: SwfClip,
): Bounds | undefined {
  if (depth > 24) return undefined;
  const leaf = source.leafBounds(id);
  if (leaf) return arithmetic.transform(leaf, matrix);
  let result: Bounds | undefined;
  for (const p of pose?.placements ?? source.displayList(id, age)) {
    const childPath = [...path, p.name ?? `#${p.depth}`],
      childPose = pose?.children.get(p.depth)?.clip,
      childAge = childPose?.age ?? source.childAge(id, age, p),
      change = override?.(p, childAge, childPath);
    result = union(
      result,
      visitBounds(
        arithmetic,
        source,
        p.charId,
        change?.age ?? childAge,
        arithmetic.multiply(matrix, change?.matrix ?? p.matrix),
        override,
        childPath,
import { rotate } from '../core/math';
import { protectionScale } from '../core/protection-size';
import { legacyShieldFilm, shieldClipFrame } from '../core/shield-art';
import type { Tank, TankPart } from '../core/types';
import { partById } from '../data/catalog';
import { INFECTED_ART, PROTECTION_ART, shieldClipSymbol } from '../data/status-art';
import type { Bounds, SwfMatrix } from './asset-pack';
import { scriptBounds, type ScriptBoundsSource } from './projectile-bounds';
import type { SwfClip } from './swf-clip';

export interface TankBoundsClips {
  part(tank: Tank, part: TankPart): SwfClip | undefined;
  status(tank: Tank, index: number): SwfClip;
  infection(tank: Tank): SwfClip;
  forcefieldPart(tank: Tank, part: TankPart): SwfClip | undefined;
  forcefieldRadius(tank: Tank): number;
  protectionRadius(tank: Tank): number;
}

/** Script width includes invisible children and masks, without filter growth or raster padding. */
export function tankScriptBounds(tank: Tank, source: ScriptBoundsSource, clips: TankBoundsClips) {
  const boxes: Bounds[] = [];
  const add = (
    id: number,
    age: number,
    x = 0,
    y = 0,
    angle = 0,
    sx = 1,
    sy = sx,
    pose?: SwfClip,
  ) => {
    const position = rotate({ x, y }, tank.rotation),
      radians = ((tank.rotation + angle) * Math.PI) / 180,
      matrix: SwfMatrix = {
        a: Math.cos(radians) * sx,
        b: Math.sin(radians) * sx,
        c: -Math.sin(radians) * sy,
        d: Math.cos(radians) * sy,
        tx: position.x * 20,
        ty: position.y * 20,
      };
    const bounds = scriptBounds(source, id, age, matrix, undefined, [], 0, pose);
    if (bounds) boxes.push(bounds);
  };
  const addPart = (part: TankPart, pose: SwfClip | undefined, aimed: boolean) => {
    const id = partById(part.type)?.symbol;
    if (!id) return;
    add(
      id,
      pose?.age ?? 1,
      part.x,
      part.y,
      aimed
        ? (tank.guns.find((gun) => gun.part.key === part.key)?.angle ?? part.rotation)
        : part.rotation,
      part.scale,
      part.scale,
      pose,
    );
  };
  for (const part of tank.design.parts)
    if (!tank.removedParts.has(part.key) && tank.displayChildren.includes(`part:${part.key}`))
      addPart(part, clips.part(tank, part), true);
  if (tank.statusDecoration && tank.displayChildren.includes('status'))
    for (const [i, mark] of tank.statusDecoration.marks.entries()) {
      const pose = clips.status(tank, i);
      add(pose.id, pose.age, mark.x, mark.y, mark.angle, 1, 1, pose);
    }
  if (tank.status.infect > 0 && tank.displayChildren.includes('infection')) {
    const pose = clips.infection(tank);
    add(
      INFECTED_ART,
      pose.age,
      0,
      0,
      tank.infectionAngle,
      (tank.radius * 1.5) / 36,
      undefined,
      pose,
    );
  }
  const scaled = (id: number, frame: number, angle: number, diameter: number, uniform = false) => {
    const scale = protectionScale(scriptBounds(source, id, 1), diameter, uniform);
    add(id, frame, 0, 0, angle, scale.x, scale.y);
  };
  for (const clip of tank.shieldClips)
    if (tank.displayChildren.includes(clip.key))
      scaled(shieldClipSymbol(clip), shieldClipFrame(clip), clip.angle, clip.diameter);
  const film = legacyShieldFilm(tank),
    turret = tank.side !== 'player',
    diameter = turret ? tank.radius * 2 : (tank.shieldDiameter ?? clips.protectionRadius(tank) * 2);
  if (film)
    scaled(
      turret ? PROTECTION_ART.turretShield : PROTECTION_ART.shield,
      turret ? Math.min(25, tank.shieldAge + 1) : tank.shieldAge + 1,
      0,
      diameter,
    );
  if (film || tank.displayChildren.includes('shield-hit'))
    scaled(
      turret ? PROTECTION_ART.turretShieldHit : PROTECTION_ART.shieldHit,
      Math.min(16, tank.shieldHitAge + 1),
      tank.shieldHitAngle,
      tank.shieldHitDiameter ?? diameter,
    );
  if (tank.forcefieldAttached && tank.displayChildren.includes('forcefield')) {
    scaled(
      PROTECTION_ART.forcefield,
      tank.forcefieldFrame,
      tank.forcefieldAngle,
      clips.forcefieldRadius(tank) * 2.1,
      true,
    );
    // Flash includes the retained silhouette mask as well as the uncut field clip.
    for (const part of tank.design.parts) addPart(part, clips.forcefieldPart(tank, part), false);
  }
  if (!boxes.length) return undefined;
  const x = Math.min(...boxes.map((box) => box.x)),
    y = Math.min(...boxes.map((box) => box.y));
  return {
    x,
    y,
    width: Math.max(...boxes.map((box) => box.x + box.width)) - x,
    height: Math.max(...boxes.map((box) => box.y + box.height)) - y,
  };
}

