function carrier(release = true) {
  const world = new World([], [], 42);
  world.player.x = 200;
  world.player.y = 0;
  const owner = createTank(
    world.nextId(),
    {
      ...STARTER,
      avatar: false,
      life: 100,
      parts: [
        STARTER.parts[0],
